<script>
(() => {
const rows=[...document.querySelectorAll('[data-count-search]')];
rows.forEach(row=>{const input=row.querySelector('input'), cell=row.querySelector('[data-row-variance]');const update=()=>{const value=input.value==='' ? null : Number(input.value)-Number(row.dataset.expected);cell.textContent=value===null ? '—' : (value>0 ? '+' : '')+value;cell.className='number sp-variance'+(value<0 ? ' negative' : value>0 ? ' positive' : '');};input.addEventListener('input',update);update();});
document.getElementById('count-item-search').addEventListener('input',event=>{const term=event.target.value.trim().toLowerCase();rows.forEach(row=>row.hidden=!row.dataset.countSearch.toLowerCase().includes(term));document.getElementById('count-no-matches').hidden=rows.some(row=>!row.hidden);});
@if(request()->boolean('count') || $errors->has('lines') || $errors->has('lines.*'))document.getElementById('physical-stock-count').showModal();@endif
})();
</script>
